
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_gam_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_gam", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.639098675814834e+00, -4.538475275927268e+00, -4.397749134205203e+00, -4.203406019912336e+00, -3.939937681422579e+00, -3.592427931228610e+00, -3.152767425303087e+00, -2.631946663043788e+00, -2.078761235298819e+00, -1.579281231054414e+00, -1.133722682745853e+00, -7.633173447806981e-01, -6.610311930149467e-01, -5.363346140509604e-01, -3.750977060292305e-01, -2.255882196493961e-01, -1.713852807397365e-01, -1.188673070290607e-01, -2.991649612386245e-02, -3.417948822060625e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


